void need(bool b,const std::string& reason){if(!b)throw std::runtime_error(reason);}
template<class F>void rejects(F fn,const char* reason){bool caught=false;try{fn();}catch(const std::exception&){caught=true;}need(caught,reason);}
std::string quote(const std::string& text){std::ostringstream f;f<<'"';for(unsigned char c:text){switch(c){case '"':f<<"\\\"";break;case '\\':f<<"\\\\";break;case '\n':f<<"\\n";break;case '\r':f<<"\\r";break;case '\t':f<<"\\t";break;default:if(c<32)f<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<unsigned(c)<<std::dec;else f<<char(c);}}f<<'"';return f.str();}
std::string sha(const fs::path& path){std::ifstream f(path,std::ios::binary);need(bool(f),"SHA input open: "+path.string());Phase45PcmDigest h;std::array<char,65536> data{};while(f.read(data.data(),data.size())||f.gcount())h.update(data.data(),std::size_t(f.gcount()));need(f.eof(),"SHA read: "+path.string());return h.finish();}
std::shared_ptr<p56::MemoryLedger> ledger(std::size_t bytes=8*1024*1024){auto p=std::make_shared<p56::MemoryLedger>(bytes);p->owner=p;return p;}
template<class Stats>void statsJson(std::ostream& f,const Stats& s){f<<"{\"updates\":"<<s.updates<<",\"fixed_event_visits\":"<<s.fixedEventVisits<<",\"fixed_appended_nodes\":"<<s.fixedAppendedNodes<<",\"dynamic_appended_nodes\":"<<s.dynamicAppendedNodes<<",\"materialized_nodes\":"<<s.materializedNodes<<",\"history_replays\":"<<s.historyReplays<<",\"diagnostic_replay_requests\":"<<s.diagnosticReplayRequests<<",\"diagnostic_comparisons\":"<<s.diagnosticComparisons<<",\"prefix_proof_pages\":"<<s.prefixProofPages<<",\"prefix_proof_nodes\":"<<s.prefixProofNodes<<",\"index_bytes_copied\":"<<s.indexBytesCopied<<",\"fixed_cache_entries\":"<<s.fixedCacheEntries<<",\"page_live_bytes\":"<<s.pageLiveBytes<<",\"page_peak_bytes\":"<<s.pagePeakBytes<<",\"page_copied_bytes\":"<<s.pageCopiedBytes<<'}';}
template<class T,std::size_t N>void sameNumbers(const std::array<T,N>& a,const std::array<T,N>& b,const char* reason){for(std::size_t i=0;i<N;++i){if constexpr(std::is_floating_point_v<T>){need(std::isfinite(a[i])&&std::isfinite(b[i]),"nonfinite decision");if constexpr(sizeof(T)==8)need(std::bit_cast<std::uint64_t>(a[i])==std::bit_cast<std::uint64_t>(b[i]),reason);else need(std::bit_cast<std::uint32_t>(a[i])==std::bit_cast<std::uint32_t>(b[i]),reason);}else need(a[i]==b[i],reason);}}
void sameEvent(const TransientEvent& a,const TransientEvent& b){need(std::tie(a.onsetFrame,a.peakFrame,a.attackEndFrame,a.endFrame)==std::tie(b.onsetFrame,b.peakFrame,b.attackEndFrame,b.endFrame)&&std::bit_cast<std::uint32_t>(a.strength)==std::bit_cast<std::uint32_t>(b.strength),"event fields changed");}
void sameMap(const p59::PersistentMap& actual,const TimeMap& expected){const auto n=actual.starts();need(actual.sourceHop()==expected.sourceHop()&&n.size()==expected.starts().size(),"map extent/hop");for(std::size_t i=0;i<n.size();++i)need(n.at(i)==expected.starts()[i],"map node "+std::to_string(i));const auto exported=actual.materialize();need(exported.events().size()==expected.events().size(),"map event count");for(std::size_t i=0;i<exported.events().size();++i)sameEvent(exported.events()[i],expected.events()[i]);}
void samePlan(const Phase39Plan& a,const Phase39Plan& b){need(std::tie(a.outcome,a.requestedFrame,a.appliedFrame,a.rampEndFrame,a.appliedOutputSample,a.completionOutputSample,a.protectedEventsSkipped,a.protectedEventsPaused,a.firstMutableFrame,a.firstSafeFrame,a.nextEventFrame,a.protectionEndFrame,a.safeFramesUsed,a.heldFrames)==std::tie(b.outcome,b.requestedFrame,b.appliedFrame,b.rampEndFrame,b.appliedOutputSample,b.completionOutputSample,b.protectedEventsSkipped,b.protectedEventsPaused,b.firstMutableFrame,b.firstSafeFrame,b.nextEventFrame,b.protectionEndFrame,b.safeFramesUsed,b.heldFrames),"Phase39 decision field differs");}
