 samePlan(a.plan,b.plan);need(std::tie(a.request.generation,a.request.target.micros,a.request.requestedInputSample,a.request.publishedOutputSample)==std::tie(b.request.generation,b.request.target.micros,b.request.requestedInputSample,b.request.publishedOutputSample)&&std::bit_cast<std::uint64_t>(a.request.transitionOutputMs)==std::bit_cast<std::uint64_t>(b.request.transitionOutputMs),"request field differs");
 need(std::tie(a.outputFrames,a.densityInput,a.statePreserved,a.changesDensity)==std::tie(b.outputFrames,b.densityInput,b.statePreserved,b.changesDensity),"planned change field differs");
 need(a.boundary.legacy==b.boundary.legacy&&a.boundary.precise==b.boundary.precise,"boundary fence differs");sameNumbers(a.boundary.processedNode,b.boundary.processedNode,"processed node");sameNumbers(a.boundary.consumedOla,b.boundary.consumedOla,"OLA fence");sameNumbers(a.boundary.consumedFir,b.boundary.consumedFir,"FIR fence");
 const auto& x=a.density;const auto& y=b.density;need(std::tie(x.safe,x.inputSample,x.candidatesTried)==std::tie(y.safe,y.inputSample,y.candidatesTried),"density decision");
 sameNumbers(x.maximumHop,y.maximumHop,"maximum hop");sameNumbers(x.maximumHopStep,y.maximumHopStep,"maximum hop step");sameNumbers(x.minimumWeight,y.minimumWeight,"minimum weight");sameNumbers(x.minimumLocalSpeed,y.minimumLocalSpeed,"minimum local speed");sameNumbers(x.maximumLocalSpeed,y.maximumLocalSpeed,"maximum local speed");sameNumbers(x.reconstructedHistoryMismatches,y.reconstructedHistoryMismatches,"history mismatches");sameNumbers(x.reconstructedHistoryMaxDifference,y.reconstructedHistoryMaxDifference,"history difference");sameNumbers(x.actualWeight,y.actualWeight,"actual weight");sameNumbers(x.predictedActualWeight,y.predictedActualWeight,"predicted weight");sameNumbers(x.weightPredictionAbsoluteError,y.weightPredictionAbsoluteError,"weight error");
