 Report(fs::path folder,std::string p,std::string s):out(std::move(folder)),preset(std::move(p)),source(std::move(s)){need(!fs::exists(out),"fresh output required");need(fs::create_directories(out),"output create");checks.open(out/"checks.jsonl");observations.open(out/"observations.jsonl");std::ofstream expected(out/"EXPECTED.json");expected<<"{\"schema\":1,\"expected\":"<<ids.size()<<",\"required_ids\":[";for(std::size_t i=0;i<ids.size();++i)expected<<(i?",":"")<<quote(ids[i]);expected<<"],\"preset\":"<<quote(preset)<<",\"source\":"<<quote(source)<<",\"audio_output\":\"NOT_RUN\",\"independent_PCM\":\"NOT_RUN\",\"performance\":\"NOT_ASSESSED\"}\n";need(bool(expected)&&bool(checks)&&bool(observations),"evidence open");}
 void pass(){need(done<ids.size(),"extra check");checks<<"{\"id\":"<<quote(ids[done++])<<",\"pass\":true}\n";checks.flush();need(bool(checks),"check write");}
