 need(p56::ImmutableSeries<long long>::pageWidth==64,"page width changed");auto memory=ledger();p56::ImmutableSeries<long long> series;std::vector<p56::ImmutableSeries<long long>> oldSeries;const auto value=[](std::size_t i){return 19LL+std::int64_t(i)*1009;};
